import type { ComponentType, SVGProps } from "react";
export type IconProps = SVGProps<SVGSVGElement> & { size?: number | string; absoluteStrokeWidth?: boolean };
export type LucideIcon = ComponentType<IconProps>;
function symbol(name: string, path: string): LucideIcon {
  return function ReferenceSymbol({ size = 24, absoluteStrokeWidth: _absoluteStrokeWidth, strokeWidth: _strokeWidth, ...props }: IconProps) {
    return <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 960 960" fill="currentColor" aria-hidden={props["aria-label"] ? undefined : true} data-symbol={name} {...props}><path d={path} transform="translate(0 960) scale(1 -1)" /></svg>;
  };
}

